<script setup>
import {computed,ref,watch,onMounted} from 'vue';
import {state} from '../store';
const props=defineProps({modelValue:{default:''},placeholder:{default:'Write your content…'}});const emit=defineEmits(['update:modelValue']);const editor=ref(null);
const commands=computed(()=>state.language==='id'?[['bold','B','Tebal'],['italic','I','Miring'],['underline','U','Garis bawah'],['insertUnorderedList','• Daftar','Daftar berpoin'],['insertOrderedList','1. Daftar','Daftar bernomor'],['removeFormat','Hapus format','Hapus pemformatan']]:[['bold','B','Bold'],['italic','I','Italic'],['underline','U','Underline'],['insertUnorderedList','• List','Bullet list'],['insertOrderedList','1. List','Numbered list'],['removeFormat','Clear','Clear formatting']]);
function input(){emit('update:modelValue',editor.value.innerHTML)}
function format(command){editor.value.focus();document.execCommand(command,false,null);input()}
onMounted(()=>editor.value.innerHTML=props.modelValue||'');watch(()=>props.modelValue,value=>{if(document.activeElement!==editor.value&&editor.value.innerHTML!==(value||''))editor.value.innerHTML=value||''});
</script>
<template><div class="rich-editor"><div class="editor-toolbar" role="group" :aria-label="state.language==='id'?'Pemformatan teks':'Text formatting'"><button v-for="c in commands" :key="c[0]" type="button" @mousedown.prevent @click="format(c[0])" :aria-label="c[2]" :title="c[2]" :class="'format-'+c[0]">{{c[1]}}</button></div><div ref="editor" class="editor-body" contenteditable="true" role="textbox" aria-multiline="true" :aria-label="placeholder" :data-placeholder="placeholder" @input="input"></div></div></template>
<style scoped>
.rich-editor{min-width:0;width:100%;border:1px solid var(--border);border-radius:.75rem;overflow:hidden;background:var(--surface)}.rich-editor:focus-within{border-color:var(--color-accent);box-shadow:0 0 0 2px var(--blue-soft)}.rich-editor .editor-toolbar{display:flex;flex-wrap:wrap;gap:.5rem;padding:.75rem;background:var(--surface-alt);border-bottom:1px solid var(--border)}.editor-toolbar button{display:inline-flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;padding:.5rem .75rem;border:1px solid var(--border);border-radius:.375rem;background:var(--surface);font-size:1.0625rem;line-height:1.5;color:var(--text)}.editor-toolbar button:hover,.editor-toolbar button:focus-visible{background:var(--blue-soft);color:var(--color-accent)}.format-bold{font-weight:800}.format-italic{font-style:italic}.format-underline{text-decoration:underline}.rich-editor .editor-body{width:100%;min-height:12rem;max-height:32rem;overflow:auto;padding:1rem;font-size:1.125rem;line-height:1.8;color:var(--text);overflow-wrap:anywhere;outline-offset:-3px}.editor-body:empty:before{content:attr(data-placeholder);color:var(--muted);pointer-events:none}.editor-body :deep(p+p){margin-top:.75rem}.editor-body :deep(ul),.editor-body :deep(ol){padding-left:1.5rem}.editor-body :deep(img),.editor-body :deep(table){max-width:100%}@media(max-width:600px){.rich-editor .editor-toolbar{padding:.5rem}.rich-editor .editor-body{padding:.75rem}}
</style>
